import { test } from "node:test";
import assert from "node:assert/strict";
import { parseFlags } from "../packages/cli/src/flags.js";

test("[cli-flag] --port takes a number", () => {
  assert.equal(parseFlags(["--port", "8080"]).port, 8080);
});

test("a bare flag is true", () => {
  assert.equal(parseFlags(["--verbose"]).verbose, true);
});
import { test } from "node:test";
import assert from "node:assert/strict";
import { dayKey } from "../packages/shared/src/dates.js";

process.env.TZ = "America/New_York";

test("[timezone] day keys are UTC days", () => {
  assert.equal(dayKey(new Date("2026-01-02T02:30:00Z")), "2026-01-02");
});
import { test } from "node:test";
import assert from "node:assert/strict";
import { displayName, initials } from "../packages/shared/src/format.js";

test("[null-guard] a user without a name is anonymous", () => {
  assert.equal(displayName(null), "anonymous");
  assert.equal(displayName({}), "anonymous");
});

test("display names are trimmed", () => {
  assert.equal(displayName({ name: "  Ada Lovelace " }), "Ada Lovelace");
});

test("initials", () => {
  assert.equal(initials("Ada Lovelace"), "AL");
});

